def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_c = sum(1 for o in opp if o == 'C')
    opp_d = n - opp_c
    my_d = sum(1 for m in me if m == 'D')
    total_exploit = sum(1 for m, o in history if m == 'C' and o == 'D')

    last_opp = opp[-1]

    opp_d_streak = 0
    for i in range(n - 1, -1, -1):
        if opp[i] == 'D':
            opp_d_streak += 1
        else:
            break

    mutual_d_streak = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and opp[i] == 'D':
            mutual_d_streak += 1
        else:
            break

    recent = history[-6:] if n >= 6 else history
    exploit6 = sum(1 for m, o in recent if m == 'C' and o == 'D')

    after_d_c = 0
    after_d_d = 0
    for i in range(1, n):
        if me[i - 1] == 'D':
            if opp[i] == 'C':
                after_d_c += 1
            else:
                after_d_d += 1

    if last_opp == 'D':
        if opp_c == 0:
            return 'D'

        if opp_d * 3 > n * 2 and opp_d_streak >= 4:
            return 'D'

        if mutual_d_streak >= 2 and opp_c >= opp_d and total_exploit < 3:
            return 'C'

        if exploit6 >= 2 and opp_d_streak >= 2:
            return 'D'

        if opp_d_streak <= 2 and opp_c >= opp_d:
            return 'C'

        if after_d_c > 0 and after_d_d == 0 and opp_c >= opp_d:
            return 'D'

        return 'D'

    if n >= 2 and me[n - 2] == 'D' and opp[n - 1] == 'C' and opp_c >= opp_d:
        return 'D'

    if after_d_c > 0 and after_d_d == 0 and n >= 10 and opp_c >= opp_d:
        return 'D'

    if my_d == 0 and opp_d == 0 and n >= 40:
        return 'D'

    return 'C'
